from collections import deque

class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        q = deque([root])       # BFS 队列
        res = []
        while q:
            size = len(q)       # 关键：当前队列长度 == 本层节点数
            level = []
            for _ in range(size):
                node = q.popleft()
                level.append(node.val)
                if node.left:
                    q.append(node.left)    # 先左后右，保证从左到右
                if node.right:
                    q.append(node.right)
            res.append(level)  # 一层收齐
        return res

