class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (!root) return {};                       // 空树直接返回空结果
        vector<vector<int>> res;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int size = (int)q.size();               // 关键：先锁定本层节点数
            vector<int> level;
            for (int i = 0; i < size; ++i) {        // 只弹出本层的节点
                TreeNode* node = q.front();
                q.pop();
                level.push_back(node->val);
                if (node->left) q.push(node->left);   // 先左后右入队，保证层内从左到右
                if (node->right) q.push(node->right);
            }
            res.push_back(std::move(level));        // 一层收齐，move 进结果避免拷贝
        }
        return res;
    }
};

