// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：一行，二叉树的层序序列，空节点用 null 表示（如 "3 9 20 null null 15 7"；空树为空行）
// 输出格式：一行，层序遍历结果，形如 [[3],[9,20],[15,7]]（空树输出 []）
#include <bits/stdc++.h>
using namespace std;

// 二叉树节点定义（ACM 模式需自带）
struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// 把一行按空白切成 token
vector<string> splitTokens(const string& line) {
    vector<string> tokens;
    istringstream iss(line);
    string tok;
    while (iss >> tok) tokens.push_back(tok);
    return tokens;
}

// 按层序 token 流建树：'null' 表示空节点
TreeNode* build(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;   // 空树
    TreeNode* root = new TreeNode(stoi(tokens[0]));
    queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {    // 逐个出队，依次挂左右孩子
        TreeNode* node = q.front();
        q.pop();
        if (i < tokens.size()) {                 // 先挂左孩子
            if (tokens[i] != "null") {
                node->left = new TreeNode(stoi(tokens[i]));
                q.push(node->left);
            }
            ++i;
        }
        if (i < tokens.size()) {                 // 再挂右孩子
            if (tokens[i] != "null") {
                node->right = new TreeNode(stoi(tokens[i]));
                q.push(node->right);
            }
            ++i;
        }
    }
    return root;
}

class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        if (!root) return {};                       // 空树直接返回空结果
        vector<vector<int>> res;
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            int size = (int)q.size();               // 关键：先锁定本层节点数
            vector<int> level;
            for (int i = 0; i < size; ++i) {        // 只弹出本层的节点
                TreeNode* node = q.front();
                q.pop();
                level.push_back(node->val);
                if (node->left) q.push(node->left);   // 先左后右入队，保证层内从左到右
                if (node->right) q.push(node->right);
            }
            res.push_back(std::move(level));        // 一层收齐，move 进结果避免拷贝
        }
        return res;
    }
};

int main() {
    string line;
    getline(cin, line);                         // 一行：层序序列（空行即空树）
    TreeNode* root = build(splitTokens(line));
    vector<vector<int>> res = Solution().levelOrder(root);
    string out = "[";
    for (size_t i = 0; i < res.size(); ++i) {   // 每层拼成一个子列表
        if (i) out += ',';
        out += '[';
        for (size_t j = 0; j < res[i].size(); ++j) {
            if (j) out += ',';
            out += to_string(res[i][j]);
        }
        out += ']';
    }
    cout << out << ']' << '\n';
    return 0;
}

