func levelOrder(root *TreeNode) [][]int {
	res := [][]int{}
	if root == nil {
		return res // 空树直接返回空结果
	}
	queue := []*TreeNode{root}
	for len(queue) > 0 {
		next := []*TreeNode{} // 收集下一层节点
		level := []int{}
		for _, node := range queue { // 当前 queue 恰好是本层全部节点
			level = append(level, node.Val)
			if node.Left != nil {
				next = append(next, node.Left) // 先左后右，保证层内从左到右
			}
			if node.Right != nil {
				next = append(next, node.Right)
			}
		}
		res = append(res, level) // 一层收齐
		queue = next             // 整层替换，进入下一层
	}
	return res
}
